function groupByPnrHandleTypeWithPassengers(items) {
  const groups = {};

  for (const item of items) {
    const { pnr, postSaleHandleType, passengerFirstName, passengerLastName } = item;
    const key = `${pnr}__${postSaleHandleType}`;

    if (!groups[key]) {
      groups[key] = {
        pnr,
        postSaleHandleType,
        passengers: []
      };
    }

    groups[key].passengers.push({ passengerFirstName, passengerLastName });
  }

  return Object.values(groups);
}

